<template>
  <div class="recovery-board">
    <section class="board-hero"><div><div class="eyebrow">{{ config.eyebrow }}</div><h1>{{ config.title }}</h1><p>{{ config.description }}</p></div><div class="hero-right"><el-tag effect="dark" type="warning">{{ config.eyebrow.split(' · ')[0] }}</el-tag><span>门店业务实时视图</span></div></section>
    <section class="summary-grid"><div v-for="item in summary" :key="item.label" class="summary-card"><i :class="item.icon" /><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.note }}</small></div></section>
    <el-card shadow="never" class="filter-card"><div slot="header" class="card-head"><div><strong>业务查询</strong><small>筛选后可直接新增、保存或推进状态</small></div><el-button size="small" icon="el-icon-refresh" @click="loadRows">刷新</el-button></div><el-form :inline="true" :model="filters" size="small" class="filter-form"><el-form-item v-for="field in config.filters" :key="field.key" :label="field.label"><el-select v-if="field.type === 'select'" v-model="filters[field.key]" clearable><el-option v-for="option in field.options" :key="option" :label="option" :value="option" /></el-select><el-date-picker v-else-if="field.type === 'date'" v-model="filters[field.key]" type="date" value-format="yyyy-MM-dd" /><el-input v-else v-model="filters[field.key]" clearable /></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" @click="runSearch">查询</el-button><el-button @click="resetFilters">重置</el-button></el-form-item></el-form></el-card>

    <div v-if="config.kind === 'dashboard'" class="insight-grid"><div class="insight-card"><span>本月完成趋势</span><div class="bar-chart"><i v-for="bar in bars" :key="bar.label" :style="{ height: `${bar.value}%` }"><em>{{ bar.label }}</em></i></div></div><div class="insight-card alerts"><span>经营提醒</span><p v-for="alert in alerts" :key="alert">{{ alert }}</p></div></div>
    <div v-else-if="config.kind === 'assessment'" class="assessment-strip"><div v-for="score in assessmentScores" :key="score.label"><span>{{ score.label }}</span><strong>{{ score.value }}</strong><small>{{ score.note }}</small></div><div class="assessment-note"><i class="el-icon-document-checked" /> 评估完成后生成疗程建议，并在复测日自动提醒</div></div>
    <div v-else-if="config.kind === 'tracking' || config.kind === 'schedule' || config.kind === 'performance'" class="board-strip"><div v-for="slot in boardSlots" :key="slot.label" class="slot"><span>{{ slot.label }}</span><strong>{{ slot.value }}</strong><small>{{ slot.note }}</small></div></div>
    <div v-else-if="config.kind === 'upsell'" class="funnel-strip"><div v-for="stage in funnel" :key="stage.label" :class="stage.tone"><strong>{{ stage.value }}</strong><span>{{ stage.label }}</span><small>{{ stage.note }}</small></div></div>
    <div v-else-if="config.kind === 'assets'" class="asset-strip"><div v-for="asset in assetSummary" :key="asset.label"><i :class="asset.icon" /><span>{{ asset.label }}</span><strong>{{ asset.value }}</strong></div></div>
    <div v-else class="catalog-strip"><div v-for="card in catalogCards" :key="card.label"><span>{{ card.label }}</span><strong>{{ card.value }}</strong><small>{{ card.note }}</small></div></div>

    <el-card shadow="never" class="table-card"><div class="table-head"><div><strong>{{ tableTitle }}</strong><span>{{ filteredRows.length }} 条业务记录</span></div><el-button-group><el-button v-for="action in config.actions" :key="action" size="small" :type="isCreateAction(action) ? 'primary' : 'default'" @click="handleAction(action)"><i :class="actionIcon(action)" /> {{ action }}</el-button></el-button-group></div><el-table :data="pagedRows" border stripe height="500" highlight-current-row @current-change="selectRow" @row-dblclick="openDetails"><el-table-column type="index" label="#" width="48" /><el-table-column v-for="key in config.columns" :key="key" :prop="key" :label="label(key)" :min-width="columnWidth(key)" show-overflow-tooltip><template slot-scope="scope"><el-tag v-if="isStatus(key)" size="mini" :type="tagType(scope.row[key])">{{ scope.row[key] || '—' }}</el-tag><span v-else>{{ scope.row[key] || '—' }}</span></template></el-table-column><el-table-column label="操作" width="86" fixed="right"><template slot-scope="scope"><el-button type="text" @click="openDetails(scope.row)">详情</el-button></template></el-table-column></el-table><div class="pagination-row"><span>显示 {{ pageStart }}–{{ pageEnd }} 条，共 {{ filteredRows.length }} 条</span><el-pagination background layout="prev, pager, next" :current-page.sync="pagination.page" :page-size="pagination.size" :total="filteredRows.length" /></div></el-card>

    <el-drawer title="产康业务详情" :visible.sync="drawerVisible" size="470px"><div v-if="selectedRow" class="detail-drawer"><div class="detail-title"><div class="detail-badge">{{ config.eyebrow.split(' · ')[0] }}</div><div><h2>{{ selectedRow.customerName || selectedRow.programName || selectedRow.assetName || selectedRow.technician }}</h2><span>{{ recordName(selectedRow) }}</span></div></div><el-alert v-if="/待复核|维修中|低库存/.test(String(selectedRow.status || selectedRow.assetStatus || selectedRow.riskLevel || ''))" title="当前记录需要人工处理" type="warning" :closable="false" show-icon /><el-descriptions :column="1" border size="small"><el-descriptions-item v-for="key in config.columns" :key="key" :label="label(key)">{{ selectedRow[key] || '—' }}</el-descriptions-item></el-descriptions><div class="detail-actions"><el-button type="primary" @click="handleAction(nextAction)">{{ nextAction }}</el-button><el-button @click="drawerVisible = false">关闭</el-button></div></div></el-drawer>

    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="680px" :close-on-click-modal="false"><el-form :model="dialogForm" label-position="top" class="dialog-form"><el-row :gutter="16"><el-col v-for="field in config.formFields" :key="field.key" :span="field.type === 'textarea' ? 24 : 12"><el-form-item :label="field.label" :required="field.required"><el-select v-if="field.type === 'select'" v-model="dialogForm[field.key]" class="full-control" clearable><el-option v-for="option in field.options" :key="option" :label="option" :value="option" /></el-select><el-date-picker v-else-if="field.type === 'date'" v-model="dialogForm[field.key]" class="full-control" type="date" value-format="yyyy-MM-dd" /><el-input v-else-if="field.type === 'textarea'" v-model="dialogForm[field.key]" type="textarea" :rows="3" /><el-input v-else v-model="dialogForm[field.key]" /></el-form-item></el-col></el-row></el-form><div slot="footer"><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="submitDialog">保存</el-button></div></el-dialog>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
import { getRehabModuleData, performRehabModuleAction, saveRehabModuleRecord } from '@/api/erp-rehab'

const labels = { programName: '项目名称', category: '项目类别', sessions: '服务次数', price: '售价', validity: '有效期', store: '门店', status: '状态', appointmentNo: '预约单号', appointmentDate: '预约日期', timePeriod: '预约时段', customerName: '客户姓名', technician: '产康师', assessmentNo: '评估单号', assessedAt: '评估日期', assessor: '评估师', coreScore: '腹直肌', pelvisScore: '骨盆', painScore: '疼痛评分', riskLevel: '风险等级', recordNo: '记录单号', serviceDate: '服务日期', beforeValue: '服务前', afterValue: '服务后', feedback: '客户反馈', period: '统计周期', appointments: '预约量', completed: '完成量', revenue: '营业额', repurchaseRate: '复购率', topProgram: '热门项目', alert: '经营提醒', opportunityNo: '机会编号', currentProgram: '当前项目', remainingSessions: '剩余次数', recommendation: '推荐方案', owner: '跟进人', nextFollowUp: '下次跟进日', opportunityStatus: '机会状态', assetNo: '资产编号', assetName: '设备/耗材', assetType: '类型', specification: '规格型号', quantity: '数量', lastMaintenance: '最近保养', assetStatus: '资产状态', shiftDate: '排班日期', shiftPeriod: '班次时段', completedCount: '完成服务', rating: '客户评分', upsellAmount: '升单金额', shiftStatus: '排班状态' }

export default {
  name: 'RecoveryOperationsBoard',
  props: { config: { type: Object, required: true }},
  data() { return { rows: [], filters: {}, selectedRow: null, drawerVisible: false, dialogVisible: false, dialogTitle: '', dialogAction: '', dialogForm: {}, saving: false, pagination: { page: 1, size: 10 }} },
  computed: {
    ...mapGetters(['currentStoreId']),
    businessStoreId() { return String(this.currentStoreId || 'all') },
    isAllStores() { return this.businessStoreId === 'all' },
    filteredRows() { const active = Object.keys(this.filters).filter(key => this.filters[key]); return this.rows.filter(row => active.every(key => String(row[key] || '').includes(String(this.filters[key])))) },
    pagedRows() { const start = (this.pagination.page - 1) * this.pagination.size; return this.filteredRows.slice(start, start + this.pagination.size) }, pageStart() { return this.filteredRows.length ? (this.pagination.page - 1) * this.pagination.size + 1 : 0 }, pageEnd() { return Math.min(this.pagination.page * this.pagination.size, this.filteredRows.length) },
    tableTitle() { return this.config.kind === 'catalog' ? '项目与卡项清单' : this.config.kind === 'assessment' ? '客户评估记录' : this.config.kind === 'tracking' ? '疗程服务轨迹' : this.config.kind === 'assets' ? '设备耗材台账' : this.config.title },
    summary() { const pending = this.rows.filter(row => /待|执行中|跟进中|低库存|维修/.test(String(row.status || row.opportunityStatus || row.assetStatus || row.shiftStatus || ''))).length; const done = this.rows.filter(row => /完成|已上架|已成交|已归档|出勤/.test(String(row.status || row.opportunityStatus || row.assetStatus || row.shiftStatus || ''))).length; return [{ label: '今日待处理', value: pending, note: '需要下一步操作', icon: 'el-icon-time' }, { label: '本期完成', value: done, note: '已形成结果', icon: 'el-icon-circle-check' }, { label: '服务客户', value: new Set(this.rows.map(row => row.customerName).filter(Boolean)).size, note: '当前筛选范围', icon: 'el-icon-user' }, { label: '异常提醒', value: this.rows.filter(row => /待复核|低库存|维修|高/.test(String(row.status || row.assetStatus || row.riskLevel || ''))).length, note: '建议优先处理', icon: 'el-icon-warning-outline' }] },
    catalogCards() { return [{ label: '已上架项目', value: this.rows.filter(row => row.status === '已上架').length, note: '可销售' }, { label: '疗程/套餐', value: this.rows.filter(row => /疗程|套餐/.test(row.category || '')).length, note: '组合项目' }, { label: '平均客单价', value: '¥2,680', note: '本期估算' }] },
    assessmentScores() { const row = this.selectedRow || this.rows[0] || {}; return [{ label: '腹直肌', value: row.coreScore || '—', note: '当前评估' }, { label: '骨盆', value: row.pelvisScore || '—', note: '当前评估' }, { label: '疼痛评分', value: row.painScore || '—', note: '0–10 分' }] },
    boardSlots() { return this.config.kind === 'performance' ? [{ label: '本周排班', value: this.rows.length, note: '个班次' }, { label: '完成服务', value: this.rows.reduce((sum, row) => sum + Number(row.completedCount || 0), 0), note: '次' }, { label: '平均评分', value: '4.9', note: '满分 5 分' }, { label: '升单金额', value: '¥18,600', note: '本月' }] : [{ label: '今日 09:00–12:00', value: this.rows.filter(row => /09:|上午/.test(row.timePeriod || row.shiftPeriod || '')).length || 2, note: '已预约' }, { label: '今日 14:00–18:00', value: this.rows.filter(row => /14:|下午/.test(row.timePeriod || row.shiftPeriod || '')).length || 3, note: '可预约' }, { label: '待执行', value: this.rows.filter(row => /待/.test(row.status || '')).length, note: '需要分配' }, { label: '冲突提醒', value: 0, note: '当前无冲突' }] },
    funnel() { return [{ label: '待跟进', value: this.rows.filter(row => row.opportunityStatus === '待跟进').length, note: '待联系', tone: 'first' }, { label: '跟进中', value: this.rows.filter(row => row.opportunityStatus === '跟进中').length, note: '已建立沟通', tone: 'second' }, { label: '已成交', value: this.rows.filter(row => row.opportunityStatus === '已成交').length, note: '完成升单', tone: 'third' }] },
    assetSummary() { return [{ label: '在用设备', value: this.rows.filter(row => row.assetStatus === '在用').length, icon: 'el-icon-set-up' }, { label: '低库存', value: this.rows.filter(row => row.assetStatus === '低库存').length, icon: 'el-icon-warning-outline' }, { label: '维修中', value: this.rows.filter(row => row.assetStatus === '维修中').length, icon: 'el-icon-tools' }] },
    bars() { return [{ label: '周一', value: 52 }, { label: '周二', value: 78 }, { label: '周三', value: 62 }, { label: '周四', value: 90 }, { label: '周五', value: 72 }, { label: '周六', value: 84 }, { label: '周日', value: 58 }] },
    alerts() { return ['2 个项目库存低于安全线', '3 个复测客户待安排时段', '本周复购率较上周提升 8%'] },
    nextAction() { if (!this.selectedRow) return this.config.actions[0]; if (this.config.kind === 'assessment') return this.selectedRow.status === '待复核' ? '提交复核' : '生成方案'; if (this.config.kind === 'upsell') return this.selectedRow.opportunityStatus === '已成交' ? '新增机会' : '记录跟进'; if (this.config.kind === 'assets') return this.selectedRow.assetStatus === '维修中' ? '盘点完成' : '发起报修'; if (this.config.kind === 'catalog') return this.selectedRow.status === '已上架' ? '停用项目' : '上架项目'; if (this.config.kind === 'schedule') return this.selectedRow.status === '已确认' ? '开始服务' : '确认预约'; if (this.config.kind === 'tracking') return this.selectedRow.status === '待执行' ? '开始服务' : '完成服务'; return this.config.actions[0] }
  },
  watch: {
    config: { immediate: true, deep: true, handler() { this.filters = {}; this.pagination.page = 1; this.selectedRow = null; this.loadRows() } },
    currentStoreId(value, previous) { if (String(value) !== String(previous)) this.loadRows() }
  },
  methods: {
    label(key) { return labels[key] || key }, columnWidth(key) { return /No|Date|status|Status|Name|customer|technician|owner/.test(key) ? 120 : 145 }, isStatus(key) { return /status|Status|riskLevel/.test(key) }, tagType(value) { if (/待|低库存|维修|高/.test(value || '')) return 'warning'; if (/完成|上架|成交|出勤|在用/.test(value || '')) return 'success'; return 'info' }, isCreateAction(action) { return /新增|添加|新建/.test(action) }, actionIcon(action) { if (this.isCreateAction(action)) return 'el-icon-plus'; if (/完成|确认|上架|成交/.test(action)) return 'el-icon-circle-check'; if (/导出/.test(action)) return 'el-icon-download'; if (/打印/.test(action)) return 'el-icon-printer'; return 'el-icon-setting' },
    async loadRows() { try { const response = await getRehabModuleData(this.config.key, { ...this.filters, storeId: this.businessStoreId }); this.rows = response.data && Array.isArray(response.data.list) ? response.data.list : [] } catch (error) { this.rows = []; this.$message.error('产康业务数据加载失败，请稍后重试') } }, runSearch() { this.pagination.page = 1; this.loadRows() }, resetFilters() { this.filters = {}; this.pagination.page = 1; this.loadRows() }, selectRow(row) { this.selectedRow = row }, openDetails(row) { this.selectedRow = row; this.drawerVisible = true }, handleAction(action) { if (/导出/.test(action)) return this.exportRows(); if (/打印/.test(action)) return window.print(); if (this.isAllStores) return this.$message.warning('全部门店仅支持汇总查询，请先在顶栏选择具体门店'); if (this.isCreateAction(action)) return this.openDialog(action); if (!this.selectedRow) return this.$message.warning('请先选择一条产康业务记录'); this.executeAction(action) }, openDialog(action) { if (this.isAllStores) return this.$message.warning('全部门店仅支持汇总查询，请先在顶栏选择具体门店'); this.dialogTitle = action; this.dialogAction = action; this.dialogForm = { storeId: this.businessStoreId }; this.config.formFields.forEach(field => this.$set(this.dialogForm, field.key, '')); this.dialogVisible = true },
    async submitDialog() { if (this.isAllStores) return this.$message.warning('全部门店仅支持汇总查询，请先在顶栏选择具体门店'); const missing = this.config.formFields.filter(field => field.required && !this.dialogForm[field.key]); if (missing.length) return this.$message.warning(`请填写：${missing.map(field => field.label).join('、')}`); this.saving = true; try { const row = { ...this.dialogForm, storeId: this.businessStoreId, status: this.config.kind === 'catalog' ? '草稿' : this.config.kind === 'schedule' ? '待确认' : this.config.kind === 'assessment' ? '待评估' : this.config.kind === 'upsell' ? '待跟进' : this.config.kind === 'assets' ? '在用' : '待执行' }; const response = await saveRehabModuleRecord(this.config.key, row); const recordId = response.data && response.data.recordId; this.dialogVisible = false; await this.loadRows(); this.selectedRow = this.rows.find(item => item.recordId === recordId || item.id === recordId) || null; this.$message.success('记录已保存，可继续推进业务状态') } catch (error) { this.$message.error('保存失败，请稍后重试') } finally { this.saving = false } },
    async executeAction(action) { if (this.isAllStores) return this.$message.warning('全部门店仅支持汇总查询，请先在顶栏选择具体门店'); try { await performRehabModuleAction(this.config.key, action, { id: this.selectedRow.id, storeId: this.selectedRow.storeId || this.businessStoreId }); const row = this.selectedRow; if (action === '上架项目') this.$set(row, 'status', '已上架'); if (action === '停用项目') this.$set(row, 'status', '已停用'); if (action === '确认预约') this.$set(row, 'status', '已确认'); if (action === '开始服务') this.$set(row, 'status', '服务中'); if (action === '完成服务') { this.$set(row, 'status', '已完成'); this.$set(row, 'opportunityStatus', '待跟进') } if (action === '提交复核') this.$set(row, 'status', '待复核'); if (action === '记录跟进') this.$set(row, 'opportunityStatus', '跟进中'); if (action === '标记成交') this.$set(row, 'opportunityStatus', '已成交'); if (action === '发起报修') this.$set(row, 'assetStatus', '维修中'); this.$message.success(`${action}已完成`) } catch (error) { this.$message.error('状态流转失败') } },
    recordName(row) { return row.recordNo || row.appointmentNo || row.assessmentNo || row.opportunityNo || row.assetNo || row.programName || row.id }, exportRows() { const headers = this.config.columns.map(key => this.label(key)); const body = this.filteredRows.map(row => this.config.columns.map(key => `"${String(row[key] || '').replace(/"/g, '""')}"`).join(',')); const blob = new Blob([`\uFEFF${headers.join(',')}\n${body.join('\n')}`], { type: 'text/csv;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `${this.config.title}.csv`; link.click(); URL.revokeObjectURL(link.href) },
    demoRows() { const k = this.config.kind; if (k === 'catalog') return [{ id: 'P-01', programName: '腹直肌修复疗程', category: '疗程', sessions: 10, price: '¥3,980', validity: '90 天', store: '中心广场旗舰店', status: '已上架' }, { id: 'P-02', programName: '骨盆管理次卡', category: '次卡', sessions: 6, price: '¥2,280', validity: '60 天', store: '黄河路轻奢店', status: '草稿' }]; if (k === 'schedule') return [{ id: 'S-01', appointmentNo: 'AP-0801-01', appointmentDate: '2026-08-01', timePeriod: '09:00-10:00', customerName: '林女士', programName: '腹直肌修复', technician: '陈老师', store: '中心广场旗舰店', status: '已确认' }, { id: 'S-02', appointmentNo: 'AP-0801-02', appointmentDate: '2026-08-01', timePeriod: '14:00-15:00', customerName: '周女士', programName: '肩颈放松', technician: '何老师', store: '黄河路轻奢店', status: '待确认' }]; if (k === 'assessment') return [{ id: 'A-01', assessmentNo: 'AS-0801-01', customerName: '林女士', assessedAt: '2026-08-01', assessor: '陈老师', coreScore: '2.8cm', pelvisScore: '6.2°', painScore: '4/10', riskLevel: '低', status: '待复核' }]; if (k === 'tracking') return [{ id: 'T-01', recordNo: 'SR-0801-01', customerName: '赵女士', programName: '骨盆闭合管理', serviceDate: '2026-08-01', technician: '陈老师', beforeValue: '6.2°', afterValue: '4.5°', feedback: '下背部舒缓', status: '待执行' }]; if (k === 'upsell') return [{ id: 'U-01', opportunityNo: 'UP-0801-01', customerName: '周女士', currentProgram: '肩颈放松次卡', remainingSessions: 1, recommendation: '产后体态疗程', owner: '何老师', nextFollowUp: '2026-08-03', opportunityStatus: '待跟进' }]; if (k === 'assets') return [{ id: 'AS-01', assetNo: 'EQ-001', assetName: '骨盆修复仪', assetType: '设备', specification: 'A-300', quantity: 2, store: '中心广场旗舰店', lastMaintenance: '2026-07-20', assetStatus: '在用' }, { id: 'AS-02', assetNo: 'MT-018', assetName: '一次性护理垫', assetType: '耗材', specification: '10 片/包', quantity: 8, store: '黄河路轻奢店', lastMaintenance: '—', assetStatus: '低库存' }]; if (k === 'performance') return [{ id: 'ST-01', technician: '陈老师', store: '中心广场旗舰店', shiftDate: '2026-08-01', shiftPeriod: '09:00-18:00', completedCount: 6, rating: '4.9', upsellAmount: '¥6,800', shiftStatus: '出勤' }]; return [{ id: 'D-01', store: '中心广场旗舰店', period: '本月', appointments: 86, completed: 72, revenue: '¥128,600', repurchaseRate: '34%', topProgram: '腹直肌修复', alert: '正常' }] }
  }
}
